use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let alpha: Vec<char> = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut v: int = 0
        for c in parts[0].chars() {
            let code: int = c as int
            let d = if code >= 65 { code - 55 } else { code - 48 }
            v = v * from + d
        }
        if v == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while v > 0 {
            let d: int = v % to
            out.push(alpha[d])
            v = v / to
        }
        out.reverse()
        let s: string = out.map(|c| c.to_string()).collect::<Vec<string>>().join("")
        println(s)
    }
}

